<script setup>
import { ref } from 'vue'; import { ArrowRight, UserPlus } from 'lucide-vue-next'; import { RouterLink, useRouter } from 'vue-router'; import { useAuthStore } from '../../stores/auth';
const auth = useAuthStore(); const router = useRouter(); const form = ref({ name: '', email: '', password: '' }); const error = ref('');
async function submit() { error.value = ''; try { await auth.register(form.value); router.push('/'); } catch (e) { error.value = e.response?.data?.message || Object.values(e.response?.data?.errors || {}).flat()[0] || 'Could not create your account.'; } }
</script>
<template><section class="auth-page"><div class="auth-panel"><div class="auth-icon"><UserPlus :size="20" /></div><p class="kicker">JOIN THE COLLECTION</p><h1>Make room for better.</h1><p class="auth-intro">Create an account to save your cart and track orders.</p><form @submit.prevent="submit"><label class="field-label">Name<input v-model="form.name" required autocomplete="name"></label><label class="field-label">Email<input v-model="form.email" type="email" required autocomplete="email"></label><label class="field-label">Password<input v-model="form.password" type="password" minlength="6" required autocomplete="new-password"></label><p v-if="error" class="form-error">{{ error }}</p><button class="button button-dark full-button" :disabled="auth.loading">{{ auth.loading ? 'Creating account...' : 'Create account' }} <ArrowRight :size="16" /></button></form><p class="auth-switch">Already have an account? <RouterLink to="/login">Sign in</RouterLink></p></div></section></template>
